from common import *
row=lambda k,*fs,**kw:A.row(4,k,*fs,**kw)
def field(label,val):
 val=s.simplify(val)
 return f(label,val) if val.free_symbols else n(label,val)
def lamina(num,density,bounds,X=x,Y=y,J=1,mass=True,center=True,inertia=False,gyr=False):
 vals=[s.simplify(s.integrate(density*J*mult,*bounds)) for mult in [1,X,Y,Y*Y,X*X]]
 M,My,Mx,Ix,Iy=vals;fields=[]
 if mass:fields.append(field('Mass',M))
 if center:fields.extend([field('Center of mass · x',My/M),field('Center of mass · y',Mx/M)])
 if inertia:fields.extend([field('I_x',Ix),field('I_y',Iy),field('I_0',Ix+Iy)])
 if gyr:fields.extend([field('x-radius of gyration sqrt(I_y/m)',s.sqrt(Iy/M)),field('y-radius of gyration sqrt(I_x/m)',s.sqrt(Ix/M))])
 A.integrals.append(dict(id=f'4.{num}',density=str(density),coordinates=list(map(str,[X,Y])),jacobian=str(J),bounds=[[str(t) for t in q] for q in bounds],mass=str(M),moments=list(map(str,vals[1:]))))
 row(num,*fields,why='Integrate density for mass, xρ and yρ for first moments, y²ρ and x²ρ for inertias; divide first moments by mass. Any proportionality constant k is positive.')
integral(4,1,2*x+4*y,[(x,0,5),(y,2,5)],label='Charge(C)')
integral(4,2,r*r,[(r,0,1),(theta,0,2*pi)],label='Charge(C)')
data={3:(k*y*y,[(x,1,3),(y,1,4)]),4:(1+x*x+y*y,[(x,0,a),(y,0,b)]),5:(x+y,[(y,x/2,3-x),(x,0,2)]),6:(x,[(x,y/2,1-2*y),(y,0,R(2,5))]),7:(k*y,[(y,0,1-x*x),(x,-1,1)]),8:(k*x*x,[(y,x*x,x+2),(x,-1,2)]),9:(x*y,[(y,0,s.exp(-x)),(x,0,1)]),10:(y,[(y,0,s.cos(x)),(x,-pi/2,pi/2)])}
for num,(density,bounds) in data.items():lamina(num,density,bounds)
lamina(11,r*s.sin(theta),[(r,0,1),(theta,0,pi/2)],r*s.cos(theta),r*s.sin(theta),r,mass=False)
lamina(12,r*r,[(r,0,1),(theta,0,pi/2)],r*s.cos(theta),r*s.sin(theta),r,mass=False)
lamina(13,r,[(r,1,2),(theta,0,pi)],r*s.cos(theta),r*s.sin(theta),r,mass=False)
lamina(14,1/r,[(r,1,2),(theta,0,pi)],r*s.cos(theta),r*s.sin(theta),r,mass=False)
lamina(15,k*(x*x+y*y),[(y,0,a-x),(x,0,a)],mass=False)
lamina(16,1/r,[(r,1,2*s.sin(theta)),(theta,pi/6,5*pi/6)],r*s.cos(theta),r*s.sin(theta),r,mass=False)
for num,ref in [(17,3),(18,6)]:lamina(num,*data[ref],mass=False,center=False,inertia=True)
lamina(19,k*(x*x+y*y),[(y,0,a-x),(x,0,a)],mass=False,center=False,inertia=True)
row(20,c('Harder axis','y-axis, because I_y > I_x','x-axis, because I_x > I_y','Equal difficulty'),n('I_x',s.integrate(y*y*(1+x/10),(x,0,2),(y,0,2))),n('I_y',s.integrate(x*x*(1+x/10),(x,0,2),(y,0,2))))
lamina(21,rho,[(x,0,b),(y,0,h)],mass=False,center=False,inertia=True,gyr=True)
lamina(22,rho,[(y,0,h*(1-x/b)),(x,0,b)],mass=False,center=False,inertia=True,gyr=True)
lamina(23,rho,[(r,0,a),(theta,0,pi/2)],r*s.cos(theta),r*s.sin(theta),r,mass=False,center=False,inertia=True,gyr=True)
lamina(24,rho,[(y,0,s.sin(x)),(x,0,pi)],mass=False,center=False,inertia=True,gyr=True)
lamina(25,r*r,[(r,0,s.cos(2*theta)),(theta,-pi/4,pi/4)],r*s.cos(theta),r*s.sin(theta),r,inertia=True)
lamina(26,x*x*y*y,[(y,0,x*s.exp(-x)),(x,0,2)],inertia=True)
row(27,n('a · C',R(1,2)),n('b · P(X≤1,Y≤1)',R(3,8)),n('c · P(X+Y≤1)',s.integrate(x*(1+y)/2,(y,0,1-x),(x,0,1))))
row(28,c('a · Density conditions','f≥0 and its integral over the unit square equals1','Its integral equals4','It is negative on part of the square'),n('b(i) · P(X≥1/2)',R(3,4)),n('b(ii) · Joint probability',R(3,16)),n('c · E[X]',R(2,3)),n('c · E[Y]',R(2,3)),limited=True)
row(29,c('a · Normalization','Nonnegative; (0.5∫₀∞e^(−0.5x)dx)(0.2∫₀∞e^(−0.2y)dy)=1','Integral equals0.1','Integral diverges'),n('b(i) · P(Y≥1)',s.exp(-R(1,5))),n('b(ii) · P(X≤2,Y≤4)',(1-s.exp(-1))*(1-s.exp(-R(4,5)))),n('c · E[X]',2),n('c · E[Y]',5),limited=True)
row(30,n('a · Both fail within1000hours',(1-s.exp(-1))**2),n('b · Sum of lifetimes≤1000hours',1-2/s.E),why='Assume independent exponential lifetimes; a uses the square of a CDF and b integrates over the trianglex+y≤1000.')
row(31,n('a · Probability',R(1,2),tol=1e-8),n('b · Probability',1-s.exp(-1)),why='Standardize to independent normal coordinates; a is essentially half the mass, b is a radius√2 disk in the standard bivariate normal.')
row(32,n('Probability of meeting',(1-s.exp(-30))*(1-11*s.exp(-10))/50),why='They meet iff Y≤X≤Y+30. Integrate e^(−x)y/50 over0≤y≤10 and those x bounds.')
row(33,c('a · Exposure integral','(k/20)∫∫[x²+y²≤100](20−sqrt((x−x₀)²+(y−y₀)²))dA','k∫∫[disk]distance dA','The exposure is zero everywhere'),f('b · At center',200*pi*k/3),f('b · At edge',k*(100*pi-R(1600,9))),c('Preference by exposure alone','Edge, since its exposure is lower','Center, since its exposure is lower','Exposure is constant'),limited=True)
save('section04')
